  if (d_nlp.x0) {
    casadi_copy(d_nlp.x0, 349, d_nlp.z);
  } else {
    casadi_clear(d_nlp.z, 349);
  }
  if (d_nlp.lbx) {
    casadi_copy(d_nlp.lbx, 349, d_nlp.lbz);
  } else {
    casadi_fill(d_nlp.lbz, 349, -casadi_inf);
  }
  if (d_nlp.ubx) {
    casadi_copy(d_nlp.ubx, 349, d_nlp.ubz);
  } else {
    casadi_fill(d_nlp.ubz, 349, casadi_inf);
  }
  if (d_nlp.lam_x0) {
    casadi_copy(d_nlp.lam_x0, 349, d_nlp.lam);
  } else {
    casadi_clear(d_nlp.lam, 349);
  }
  if (d_nlp.lbg) {
    casadi_copy(d_nlp.lbg, 309, d_nlp.lbz+349);
  } else {
    casadi_fill(d_nlp.lbz+349, 309, -casadi_inf);
  }
  if (d_nlp.ubg) {
    casadi_copy(d_nlp.ubg, 309, d_nlp.ubz+349);
  } else {
    casadi_fill(d_nlp.ubz+349, 309, casadi_inf);
  }
  if (d_nlp.lam_g0) {
    casadi_copy(d_nlp.lam_g0, 309, d_nlp.lam+349);
  } else {
    casadi_clear(d_nlp.lam+349, 309);
  }
  d->nlp = &d_nlp;
  d->prob = &p;
  p.nlp = &p_nlp;
  p.sp_a = casadi_s27;
  p.sp_h = casadi_s58;
  casadi_ipopt_setup(&p);
  p.eval_f = casadi_nlp_f0;
  p.eval_g = casadi_nlp_g0;
  p.eval_grad_f = casadi_nlp_grad_f0;
  p.eval_jac_g = casadi_nlp_jac_g0;
  p.eval_h = casadi_nlp_hess_l0;
  casadi_ipopt_init(d, &arg, &res, &iw, &w);
